// Catalogue of audit rules: default severity, category, the fix to suggest,
// and acceptance criteria a coding agent can verify. Severity scale:
// critical > high > medium > low > info.

export const SEVERITIES = ['critical', 'high', 'medium', 'low', 'info'];

export const RULES = {
  // Page / network
  'page-http-error': { category: 'network', severity: 'high', title: 'Page returns an HTTP error',
    fix: 'Serve the page with a 2xx status, or remove/redirect links that point to it.',
    acceptance: ['The URL responds with 200 (or a 3xx to a working page).'] },
  'page-load-failed': { category: 'network', severity: 'high', title: 'Page failed to load',
    fix: 'Make the page load within 25s without network errors.', acceptance: ['The page reaches DOMContentLoaded without errors.'] },
  'console-error': { category: 'console', severity: 'medium', title: 'Console error',
    fix: 'Fix the code path that logs this error (or stop logging expected conditions as errors).',
    acceptance: ['Loading and using the page produces no console.error output.'] },
  'page-exception': { category: 'console', severity: 'high', title: 'Uncaught JavaScript exception',
    fix: 'Handle the failing case; uncaught exceptions can leave the UI half-initialised.',
    acceptance: ['No uncaught exceptions (pageerror) while loading or interacting with the page.'] },
  'request-failed': { category: 'network', severity: 'medium', title: 'Failed network request',
    fix: 'Fix the endpoint or the URL the page requests; handle failures gracefully in the UI.',
    acceptance: ['Every request the page makes on load returns 2xx/3xx.'] },
  'broken-link': { category: 'link', severity: 'high', title: 'Broken link',
    fix: 'Point the link at an existing page or remove it.', acceptance: ['The link target responds with 2xx/3xx.'] },
  'broken-anchor': { category: 'link', severity: 'low', title: 'In-page anchor points to a missing id',
    fix: 'Add the target id to the section, or fix the href.', acceptance: ['document.getElementById(<anchor>) exists.'] },

  // Images
  'img-missing-alt': { category: 'image', severity: 'medium', title: 'Image without alt attribute',
    fix: 'Add alt text describing the image, or alt="" if it is purely decorative.',
    acceptance: ['Every <img> has an alt attribute; informative images have meaningful alt text.'] },
  'img-broken': { category: 'image', severity: 'medium', title: 'Image fails to load',
    fix: 'Fix the image URL or asset pipeline.', acceptance: ['The image loads (naturalWidth > 0).'] },
  'role-img-no-name': { category: 'image', severity: 'medium', title: 'role="img" element without an accessible name',
    fix: 'Add aria-label or aria-labelledby.', acceptance: ['The element exposes a non-empty accessible name.'] },

  // Layout
  'horizontal-overflow': { category: 'layout', severity: 'high', title: 'Horizontal scrolling / content wider than the viewport',
    fix: 'Constrain the offending element (max-width: 100%, flex-wrap, min-width: 0 on flex children, overflow-wrap: anywhere for long strings) or make wide content scroll inside its own container.',
    acceptance: ['document.documentElement.scrollWidth <= clientWidth at 390px and 1440px.'] },
  'text-clipped': { category: 'layout', severity: 'medium', title: 'Text is clipped by its container',
    fix: 'Let the container grow (remove fixed height/width), wrap the text, or truncate deliberately with text-overflow: ellipsis and a title/tooltip.',
    acceptance: ['The element\'s scrollWidth/scrollHeight do not exceed its client size, or truncation is explicit.'] },
  'text-overlap': { category: 'layout', severity: 'medium', title: 'Overlapping text',
    fix: 'Remove the absolute positioning/negative margins causing the overlap, or reserve space for both elements.',
    acceptance: ['The two text boxes do not intersect at 390px and 1440px.'] },
  'tap-target-small': { category: 'layout', severity: 'medium', title: 'Tap target too small',
    fix: 'Make the target at least 24x24 CSS px (44x44 recommended) via padding or min-width/min-height, or add spacing from neighbouring targets.',
    acceptance: ['The element\'s bounding box is >= 24x24 CSS px at 390px width (WCAG 2.5.8).'] },

  // Keyboard / focus
  'focus-not-visible': { category: 'keyboard', severity: 'medium', title: 'No visible focus indicator',
    fix: 'Add a :focus-visible style (e.g. outline: 2px solid currentColor; outline-offset: 2px); never remove outlines without a replacement.',
    acceptance: ['Tabbing to the element shows a clearly visible focus indicator (WCAG 2.4.7).'] },
  'keyboard-trap': { category: 'keyboard', severity: 'high', title: 'Keyboard focus is trapped',
    fix: 'Let Tab/Shift+Tab move focus out of the component (or provide Esc for modal widgets).',
    acceptance: ['Repeated Tab presses move focus through and beyond the element (WCAG 2.1.2).'] },
  'focus-invisible-element': { category: 'keyboard', severity: 'medium', title: 'Focus moves to an invisible element',
    fix: 'Remove hidden elements from the tab order (hidden attribute, display:none, inert, or tabindex="-1" while collapsed).',
    acceptance: ['Every element reached with Tab is visible on screen.'] },
  'positive-tabindex': { category: 'keyboard', severity: 'low', title: 'Positive tabindex overrides the natural focus order',
    fix: 'Use tabindex="0" (or none) and reorder the DOM instead.', acceptance: ['No element has tabindex > 0.'] },
  'focus-order': { category: 'keyboard', severity: 'low', title: 'Focus order does not follow the visual order',
    fix: 'Make DOM order match visual order (avoid CSS order/absolute positioning that reorders interactive elements).',
    acceptance: ['Tab moves top-to-bottom, left-to-right through the page (WCAG 2.4.3).'] },
  'clickable-not-focusable': { category: 'keyboard', severity: 'medium', title: 'Clickable element is not keyboard accessible',
    fix: 'Use a <button>/<a href>, or add role, tabindex="0" and Enter/Space key handlers.',
    acceptance: ['The control can be reached with Tab and activated with Enter/Space (WCAG 2.1.1).'] },
  'dead-button': { category: 'interaction', severity: 'medium', title: 'Button does nothing when clicked',
    fix: 'Wire up the click handler, disable the control until it is usable, or remove it.',
    acceptance: ['Clicking the control produces a visible change (navigation, DOM update, dialog, or request).'] },

  // Forms
  'field-no-accessible-name': { category: 'form', severity: 'high', title: 'Form field has no accessible name',
    fix: 'Add a visible <label for="..."> (preferred) or aria-label/aria-labelledby.',
    acceptance: ['Screen readers announce a name for the field (WCAG 1.3.1, 4.1.2).'] },
  'placeholder-as-label': { category: 'form', severity: 'medium', title: 'Placeholder used instead of a label',
    fix: 'Add a persistent visible label; keep the placeholder for an example value only.',
    acceptance: ['The field has a visible <label> that stays visible while typing.'] },
  'placeholder-empty': { category: 'form', severity: 'low', title: 'Empty placeholder attribute',
    fix: 'Remove placeholder="" or give it a useful example value.', acceptance: ['No field has an empty placeholder attribute.'] },
  'placeholder-misleading': { category: 'form', severity: 'medium', title: 'Placeholder contradicts the field\'s purpose',
    fix: 'Make the placeholder describe the same data the label/name asks for.',
    acceptance: ['Placeholder and label refer to the same kind of data.'] },
  'placeholder-pattern-mismatch': { category: 'form', severity: 'low', title: 'Placeholder example would fail the field\'s own validation',
    fix: 'Use an example value that satisfies the pattern, or fix the pattern.',
    acceptance: ['Typing the placeholder text into the field passes validation.'] },
  'format-hint-missing': { category: 'form', severity: 'low', title: 'Formatted field gives no format hint',
    fix: 'Describe the expected format in visible help text linked with aria-describedby (and keep the pattern\'s title attribute in sync).',
    acceptance: ['The expected format is visible before the user types (WCAG 3.3.2).'] },
  'required-marker-not-enforced': { category: 'form', severity: 'medium', title: 'Field is marked required but not validated as required',
    fix: 'Add the required attribute (or aria-required="true" plus your own validation) so empty submissions are blocked.',
    acceptance: ['Submitting with the field empty is blocked with an error on this field.'] },
  'required-not-indicated': { category: 'form', severity: 'low', title: 'Required field is not visibly marked',
    fix: 'Mark required fields in the label (e.g. "Email (required)" or * with a legend).',
    acceptance: ['Every required field is visibly identified before submission (WCAG 3.3.2).'] },
  'label-for-missing-target': { category: 'form', severity: 'medium', title: 'Label points to a non-existent field id',
    fix: 'Make <label for> match the input id.', acceptance: ['Each label for= resolves to a form control.'] },
  'duplicate-id': { category: 'form', severity: 'medium', title: 'Duplicate id on form controls',
    fix: 'Give each control a unique id so labels and aria references resolve.', acceptance: ['Control ids are unique in the document.'] },
  'autocomplete-missing': { category: 'form', severity: 'low', title: 'Personal-data field lacks autocomplete',
    fix: 'Add the matching autocomplete token (email, tel, given-name, postal-code, ...).',
    acceptance: ['The field has the correct autocomplete token (WCAG 1.3.5).'] },
  'wrong-input-type': { category: 'form', severity: 'medium', title: 'Field uses a generic input type',
    fix: 'Use the semantic input type (email/tel/url/number) or inputmode so browsers validate and show the right keyboard.',
    acceptance: ['The field uses the semantic type for its data.'] },
  'field-accepts-invalid': { category: 'form', severity: 'high', title: 'Field accepts an invalid value without feedback',
    fix: 'Validate the value (type/pattern/your validator) and show an error next to the field when it is wrong.',
    acceptance: ['Entering the invalid probe value and leaving the field (or submitting) shows an error and marks the field aria-invalid="true".'] },
  'validation-no-feedback': { category: 'form', severity: 'high', title: 'Invalid value produces no visible error (novalidate)',
    fix: 'The form disables native validation (novalidate) but shows no custom error: render an error message or drop novalidate.',
    acceptance: ['An error message is visible and programmatically associated with the field.'] },
  'validation-vague-message': { category: 'form', severity: 'low', title: 'Validation message is vague',
    fix: 'Say what is wrong and how to fix it (e.g. "Enter an email like name@example.com").',
    acceptance: ['Error text names the field and the expected format (WCAG 3.3.3).'] },
  'validation-message-not-associated': { category: 'form', severity: 'medium', title: 'Error message is not announced or linked to the field',
    fix: 'Link the message with aria-describedby/aria-errormessage, set aria-invalid="true", and/or use role="alert".',
    acceptance: ['Screen readers announce the error when it appears and when the field is focused (WCAG 3.3.1, 4.1.3).'] },
  'rejects-valid-data': { category: 'form', severity: 'low', title: 'Field rejects realistic valid data',
    fix: 'Relax the validation (pattern/min/max/length) so real values are accepted.',
    acceptance: ['The realistic test value passes validation.'] },
  'empty-required-submitted': { category: 'form', severity: 'high', title: 'Form submits with required fields empty',
    fix: 'Block submission until required fields are filled; validate on the server as well.',
    acceptance: ['Submitting the empty form is blocked client-side and rejected by the server with a field-level error.'] },
  'submit-server-error': { category: 'form', severity: 'high', title: 'Submitting valid data returns a server error',
    fix: 'Fix the endpoint that handles this form.', acceptance: ['Submitting valid test data returns 2xx/3xx and shows a success state.'] },
  'submit-no-feedback': { category: 'form', severity: 'medium', title: 'Submitting gives no feedback',
    fix: 'Show a success message, navigate, or show errors after submit.', acceptance: ['After submit the user sees a confirmation or an error.'] },
  'submit-blocked-valid': { category: 'form', severity: 'medium', title: 'Form blocks submission of valid-looking data',
    fix: 'Check the validators of the listed fields; they reject realistic values.', acceptance: ['Realistic data passes client-side validation.'] },
  'fill-failed': { category: 'form', severity: 'info', title: 'Field could not be filled automatically',
    fix: 'Usually a custom widget; check it works with keyboard and has a native fallback.', acceptance: [] },
  'sensitive-field-skipped': { category: 'form', severity: 'info', title: 'Sensitive field left empty by policy',
    fix: 'None; payment, bank and government-ID fields are never filled by the audit.', acceptance: [] },

  // axe
  axe: { category: 'a11y', severity: 'medium', title: 'Accessibility violation', fix: '', acceptance: [] },
};

export function axeSeverity(impact) {
  return { critical: 'critical', serious: 'high', moderate: 'medium', minor: 'low' }[impact] || 'medium';
}

export function severityRank(s) {
  const i = SEVERITIES.indexOf(s);
  return i < 0 ? 9 : i;
}
